    for c,o in pairs:
        dr=min(r for r,_ in o['cells'])-min(r for r,_ in c['cells'])
        dc=min(cc for _,cc in o['cells'])-min(cc for _,cc in c['cells'])
        print(' col',c['color'],'top',min(r for r,_ in c['cells']),'left',min(cc for _,cc in c['cells']),'delta',(dr,dc))

